<?php
require_once __DIR__.'/vehicles.php'; require_once __DIR__.'/criminals.php';
function rangers_fetch_general_fines():array{$x=[];foreach(rangers_firebase_keyed_rows('general_fines') as $key=>$fine)$x[]=['storage_id'=>$key]+$fine;usort($x,fn($a,$b)=>strcmp($b['issued_at']??'',$a['issued_at']??''));return array_map(fn($f)=>['id'=>$f['fine_code'],'storage_id'=>$f['storage_id'],'nombre'=>$f['person_name'],'agente'=>$f['issued_by_name']??'','sancion'=>$f['sanction'],'valor'=>rangers_format_currency((float)$f['amount']),'observaciones'=>$f['observations']??''],$x);}
function rangers_create_general_fine(array $d,mixed $uid,string $agent):array{$amount=rangers_parse_currency($d['valor']??'0');$fine=['fine_code'=>'MG-'.date('ymdHis').random_int(10,99),'person_name'=>strtoupper(trim($d['nombre']??'')),'issued_by_user_id'=>$uid,'issued_by_name'=>strtoupper(trim($agent)),'sanction'=>strtoupper(trim($d['sancion']??'')),'amount'=>$amount,'observations'=>strtoupper(trim($d['observaciones']??'')),'issued_at'=>date('Y-m-d H:i:s')];rangers_firebase_set('general_fines/'.rangers_new_id(),$fine);rangers_sync_general_fine_to_criminal(['nombre'=>$fine['person_name'],'sancion'=>$fine['sanction'],'valor'=>rangers_format_currency($amount)]);return ['id'=>$fine['fine_code'],'nombre'=>$fine['person_name'],'agente'=>$fine['issued_by_name'],'sancion'=>$fine['sanction'],'valor'=>rangers_format_currency($amount),'observaciones'=>$fine['observations']];}
function rangers_update_general_fine(string $id,array $d):?array{$fine=rangers_firebase_get('general_fines/'.$id);if(!$fine)throw new RuntimeException('Multa no encontrada.');rangers_firebase_update('general_fines/'.$id,['person_name'=>strtoupper(trim($d['nombre']??$fine['person_name'])),'issued_by_name'=>strtoupper(trim($d['agente']??$fine['issued_by_name']??'')),'sanction'=>strtoupper(trim($d['sancion']??$fine['sanction'])),'amount'=>rangers_parse_currency((string)($d['valor']??$fine['amount'])),'observations'=>strtoupper(trim($d['observaciones']??$fine['observations']??'')),'updated_at'=>date('Y-m-d H:i:s')]);foreach(rangers_fetch_general_fines() as $item)if($item['storage_id']===$id)return $item;return null;}
function rangers_delete_general_fine(string $id):void{if(!rangers_firebase_get('general_fines/'.$id))throw new RuntimeException('Multa no encontrada.');rangers_firebase_delete('general_fines/'.$id);}
